scripts.script:
if (!Macros.checkStance(actor, args)) return;
const effectData = thisItem.effects.getName("神风刀气").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);
actor.showFloatyText("神风刀气 +1", { fill: "#00FF00" });

if (!args.isHit) return;
const daoqi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "shenfeng_daoqi");
if (!daoqi) return;
const stacks = daoqi.getFlag("xjzl-system", "stacks") || 1;

const use = await foundry.applications.api.DialogV2.confirm({
    window: { title: "风起云涌" },
    content: `<p>命中目标！是否消耗全部 <b>${stacks}</b> 层神风刀气以禁足目标 ${stacks} 回合？</p>`,
    rejectClose: false
});

if (use) {
    await game.xjzl.api.effects.removeEffect(actor, "shenfeng_daoqi", stacks);
    const rootData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    if (rootData) {
        rootData.duration = { rounds: stacks };
        await game.xjzl.api.effects.addEffect(args.target, rootData);
        ui.notifications.info(`${actor.name} 消耗 ${stacks} 层刀气，禁足 ${args.target.name} ${stacks} 回合！`);
    }
}

if (!args.isHit) return;
const effectData = thisItem.effects.getName("神风刀气").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData, 2);
actor.showFloatyText("神风刀气 +2", { fill: "#00FF00" });

const daoqi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "shenfeng_daoqi");
const bonusRounds = daoqi ? (daoqi.getFlag("xjzl-system", "stacks") || 1) : 0;
const lvl = Math.max(1, move.computedLevel || 1);
const baseRounds = 1 + (lvl - 1);
const bleedDmg = 40 + (lvl - 1) * 10;
const totalRounds = baseRounds + bonusRounds;

const content = `
<div class="xjzl-chat-card">
   <div style="font-weight:bold; border-bottom:1px solid #ccc;">刀气旋风 (区域效果)</div>
   <div style="font-size:0.9em; padding-top:5px;">
       <p>持续 <b>${totalRounds}</b> 回合 (含刀气加成)。</p>
       <p>区域内开始回合的所有人流失 <b>${bleedDmg}</b> 点气血。</p>
       <p style="color:#888;">该区域视作[大风]天气。</p>
   </div>
</div>`;
ChatMessage.create({ user: game.user.id, speaker: ChatMessage.getSpeaker({ actor: actor }), content: content });

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    args.output.bonusDesc.push("可消耗[易水寒]触发额外效果");
}

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    const choice = await foundry.applications.api.DialogV2.wait({
        window: { title: "消耗易水寒" },
        content: `<p>是否消耗[易水寒]？请选择效果：</p>
                  <div style="display:flex; flex-direction:column; gap:5px;">
                    <label><input type="radio" name="eff" value="1"> 易水湭寒: 1米内目标倒地</label>
                    <label><input type="radio" name="eff" value="2"> 慷慨送行: 本招伤害+10</label>
                    <label><input type="radio" name="eff" value="3"> 壮士断腕: 怒气+1</label>
                    <label><input type="radio" name="eff" value="0" checked> 不消耗</label>
                  </div>`,
        buttons:[{ action: "ok", label: "确定", icon: "fas fa-check", callback: (e, b) => b.form.elements.eff.value }],
        rejectClose: false
    });
    if (choice && choice !== "0") {
        await han.delete();
        if (choice === "2") {
            args.flags.damageResult.damage += 10;
            args.flags.damageResult.breakdown += "\n+ 易水寒(慷慨送行): 10";
        } else if (choice === "3") {
            const r = S.resources.rage;
            if (r.value < r.max && !actor.xjzlStatuses.noRecoverRage) {
                await actor.changeResources({ "system.resources.rage.value": r.value + 1 }, { cause: "script", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
                actor.showFloatyText("怒气 +1", { fill: "#ff4500" });
            }
        } else if (choice === "1") {
            args.flags.yishui_prone = true;
        }
    }
}

if (args.isHit && args.isCrit) {
    const eff = thisItem.effects.getName("易水寒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
}
if (args.flags.yishui_prone && args.isHit) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
    ui.notifications.info("易水寒：目标已倒地，若1米内有其他目标请手动施加倒地！");
}

if (args.isBroken && Macros.checkStance(actor, args)) {
    const eff = thisItem.effects.getName("易水寒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
    ui.notifications.warn("架招被破！获得易水寒，可立即施展【图穷匕见】！");
}

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    args.output.bonusDesc.push("可消耗[易水寒]触发额外效果");
}

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    const choice = await foundry.applications.api.DialogV2.wait({
        window: { title: "消耗易水寒" },
        content: `<p>是否消耗[易水寒]？请选择效果：</p>
                  <div style="display:flex; flex-direction:column; gap:5px;">
                    <label><input type="radio" name="eff" value="1"> 易水湭寒: 1米内目标倒地</label>
                    <label><input type="radio" name="eff" value="2"> 慷慨送行: 本招伤害+10</label>
                    <label><input type="radio" name="eff" value="3"> 壮士断腕: 怒气+1</label>
                    <label><input type="radio" name="eff" value="0" checked> 不消耗</label>
                  </div>`,
        buttons:[{ action: "ok", label: "确定", icon: "fas fa-check", callback: (e, b) => b.form.elements.eff.value }],
        rejectClose: false
    });
    if (choice && choice !== "0") {
        await han.delete();
        if (choice === "2") {
            args.flags.damageResult.damage += 10;
            args.flags.damageResult.breakdown += "\n+ 易水寒(慷慨送行): 10";
        } else if (choice === "3") {
            const r = S.resources.rage;
            if (r.value < r.max && !actor.xjzlStatuses.noRecoverRage) {
                await actor.changeResources({ "system.resources.rage.value": r.value + 1 }, { cause: "script", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
                actor.showFloatyText("怒气 +1", { fill: "#ff4500" });
            }
        } else if (choice === "1") {
            args.flags.yishui_prone = true;
        }
    }
}

if (args.isBroken) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
    const lianji = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "lianji"));
    await game.xjzl.api.effects.addEffect(actor, lianji);
    ui.notifications.info("图穷匕见！击倒目标并获得连击。");
}
if (args.flags.yishui_prone && args.isHit) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
    ui.notifications.info("易水寒：目标已倒地，若1米内有其他目标请手动施加倒地！");
}

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    const mp = S.resources.mp.value;
    args.output.damage += mp;
    args.output.bonusDesc.push(`预估 易水寒(濒死一击): +${mp}`);
}

const han = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "yishui_han");
if (han) {
    const mp = S.resources.mp.value;
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "不复还" },
        content: `<p>是否消耗[易水寒]发动濒死一击？</p><p>将清空所有内力(${mp})转为伤害，暴击阈值-2。</p>`,
        rejectClose: false
    });
    if (confirm) {
        await han.delete();
        await actor.changeResources({ "system.resources.mp.value": 0 }, { cause: "moveCost", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        args.flags.critThresholdMod += 2;
        args.flags.damageResult.breakdown += `\n+ 易水寒(濒死一击): ${mp}`;
    } else {
        args.flags.damageResult.damage -= mp;
        args.flags.damageResult.breakdown += `\n- 拒绝消耗易水寒: -${mp}`;
    }
}

if (!Macros.checkStance(actor, args)) return;
const eff = thisItem.effects.getName("回风").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
actor.showFloatyText("气纳四方，获得回风", { fill: "#00ff00" });

const hf = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huifeng");
if (hf && args.move.name.includes("风")) {
    const stacks = hf.getFlag("xjzl-system", "stacks") || 1;
    args.flags.critThresholdMod += stacks;
}

if (args.isHit && !args.target.system.martial?.stanceActive) {
    const eff = thisItem.effects.getName("回风").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);
}

const hf = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huifeng");
if (hf) {
    args.output.bonusDesc.push(`可消耗回风提升虚招值 (每层+1)`);
}

const hf = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huifeng");
if (hf) {
    const maxStacks = hf.getFlag("xjzl-system", "stacks") || 1;
    if (args.move.name.includes("风")) {
        args.flags.critThresholdMod += maxStacks;
    }

    const result = await foundry.applications.api.DialogV2.prompt({
        window: { title: "无风起浪" },
        content: `<p>当前拥有 ${maxStacks} 层[回风]。</p><label>输入要消耗的层数以增加虚招值 (0不消耗):</label>
                  <input type="number" name="consume" value="0" min="0" max="${maxStacks}">`,
        ok: { callback: (e, b) => parseInt(b.form.elements.consume.value) || 0 },
        rejectClose: false
    });
    if (result > 0) {
        const consume = Math.min(result, maxStacks);
        await game.xjzl.api.effects.removeEffect(actor, "huifeng", consume);
        args.flags.bonusFeint += consume;
        ui.notifications.info(`消耗 ${consume} 层回风，虚招值 +${consume}`);
    }
}

if (args.isBroken) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);

    const chizhi = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "chizhi"));
    if (chizhi) {
        chizhi.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, chizhi);
    }
}

const hf = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "huifeng");
if (hf && args.move.name.includes("风")) {
    const stacks = hf.getFlag("xjzl-system", "stacks") || 1;
    args.flags.critThresholdMod += stacks;
}
const count = await foundry.applications.api.DialogV2.prompt({
    window: { title: "风起八方" },
    content: `<label>摄入地上的匕首数量 (每把伤害+10，并获得1层回风):</label><input type="number" name="cnt" value="0" min="0">`,
    ok: { callback: (e, b) => parseInt(b.form.elements.cnt.value) || 0 },
    rejectClose: false
});
if (count > 0) {
    args.flags.damageResult.damage += (count * 10);
    args.flags.damageResult.breakdown += `\n+ 摄入匕首 x${count}: ${count * 10}`;
    const eff = thisItem.effects.getName("回风").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff, count);
    actor.showFloatyText(`吸收匕首 x${count}`, { fill: "#00ff00" });
}

if (args.isHit && !args.target.system.martial?.stanceActive) {
    const prone = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "prone"));
    await game.xjzl.api.effects.addEffect(args.target, prone);
}

if (args.hitCount > 0) {
    const effectData = thisItem.effects.getName("刀意").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effectData);
    actor.showFloatyText("刀意 +1", { fill: "#00FF00" });
}

if (args.isHit) {
    const effectData = thisItem.effects.getName("神风刀气").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effectData);
    actor.showFloatyText("神风刀气 +1", { fill: "#00FF00" });
}

if (Macros.checkStance(actor, args)) {
    const daoqi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "shenfeng_daoqi");
    const stacks = daoqi ? (daoqi.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 3) {
        ui.notifications.info(`${actor.name} 可消耗3层刀气无消耗施展【风绝奔属】或【惊风落雨】！`);
        actor.showFloatyText("可无耗反击", { fill: "#00FFFF" });
    }
}

const daoqi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "shenfeng_daoqi");
if (daoqi) {
    const stacks = daoqi.getFlag("xjzl-system", "stacks") || 1;
    const use = await foundry.applications.api.DialogV2.confirm({
        window: { title: "神灭风消" },
        content: `<p>是否消耗全部 <b>${stacks}</b> 层神风刀气强化攻击？</p><p>每层附加 20 流失伤害，3层附加禁绝。</p>`,
        rejectClose: false
    });

    if (use) {
        actor.wuxue_shenfeng_stacks = stacks;
        await game.xjzl.api.effects.removeEffect(actor, "shenfeng_daoqi", stacks);
        ui.notifications.info(`消耗 ${stacks} 层刀气强化神灭风消！`);
    } else {
        actor.wuxue_shenfeng_stacks = 0;
    }
} else {
    actor.wuxue_shenfeng_stacks = 0;
}

if (args.isHit) {
    const stacks = actor.wuxue_shenfeng_stacks || 0;
    if (stacks > 0) {
        await args.target.applyDamage({
            amount: stacks * 20,
            type: "liushi",
            attacker: actor,
            isHit: true
        });
        if (stacks >= 3) {
            const jinjue = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jinjue"));
            if (jinjue) {
                jinjue.duration = { rounds: 3 };
                await game.xjzl.api.effects.addEffect(args.target, jinjue);
            }
        }
    }
}

const effectData = thisItem.effects.getName("杀念").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);

const lvl = Math.max(1, move.computedLevel || 1);
const gain = 10 + (lvl - 1) * 10;

const content = `
<div class="xjzl-chat-card" style="padding-left: 5px;">
    <div style="border-left: 4px solid #8b0000; background: rgba(139, 0, 0, 0.05); padding: 5px;">
        <div style="font-weight:bold; color:#8b0000; margin-bottom: 4px;"><i class="fas fa-skull"></i> 杀意凝练完成</div>
        <div style="font-size: 0.9em; color: #555;">
            请手动将 <b>杀戮值</b> 增加 <span style="color:red; font-weight:bold;">${gain}</span> 点。<br>
            <span style="font-size: 0.85em; color: #888;">（注：上限加至 90，不可因此增长杀孽）</span>
        </div>
    </div>
</div>`;
ChatMessage.create({
    user: game.user.id,
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: content
});

if ((args.move.type === "basic" && args.move.id !== 'opportunity-attack')) return;

const shanie = actor.system.resources.shanie || 0;
const wuxueItem = actor.itemTypes.wuxue.find(w => w.name === "杀意动");
const moveData = wuxueItem?.system.moves.find(m => m.name === "杀意动");
const lvl = Math.max(1, moveData?.computedLevel || 1);

const maxExtra = 10 + (lvl - 1) * 10;
const extra = Math.min(maxExtra, shanie);
const bonus = 10 + extra;

args.output.damage += bonus;
args.output.bonusDesc.push(`杀念: +${bonus} (需消耗20杀戮)`);

if ((args.move.type === "basic" && args.move.id !== 'opportunity-attack')) return;

const shalu = actor.system.resources.shalu.value;
const shanie = actor.system.resources.shanie || 0;

const wuxueItem = actor.itemTypes.wuxue.find(w => w.name === "杀意动");
const moveData = wuxueItem?.system.moves.find(m => m.name === "杀意动");
const lvl = Math.max(1, moveData?.computedLevel || 1);

const maxExtra = 10 + (lvl - 1) * 10;
const extra = Math.min(maxExtra, shanie);
const bonus = 10 + extra;

if (shalu >= 20) {
    const use = await foundry.applications.api.DialogV2.confirm({
        window: { title: '杀念', icon: 'fas fa-skull' },
        content: `<p>预计算伤害已包含 <b>+${bonus}</b> 加成。</p><p>是否消耗 20 点杀戮值以生效此加成？</p>`,
        yes: { label: "消耗 (保留加成)", icon: "fas fa-check" },
        no: { label: "不消耗 (移除加成)", icon: "fas fa-times" }
    });
    if (use) {
        await actor.update({ 'system.resources.shalu.value': shalu - 20 });

        const content = `
        <div class="xjzl-chat-card" style="padding-left: 5px;">
            <div style="border-left: 4px solid #8b0000; background: rgba(139, 0, 0, 0.05); padding: 5px;">
                <span style="color:#8b0000; font-weight:bold;"><i class="fas fa-tint"></i> 杀意涌动！伤害+${bonus}</span>
            </div>
        </div>`;
        ChatMessage.create({
            user: game.user.id,
            speaker: ChatMessage.getSpeaker({actor: actor}),
            content: content
        });
    } else {
        args.flags.damageResult.damage -= bonus;
        args.flags.damageResult.breakdown += `\n- 未消耗：移除杀念加成 (-${bonus})`;
    }
} else {
    args.flags.damageResult.damage -= bonus;
    args.flags.damageResult.breakdown += `\n- 未消耗：杀戮值不足 (-${bonus})`;
}
